import{_ as t,o,c as d,ax as a}from"./chunks/framework.Bnt0oLax.js";const b=JSON.parse('{"title":"Project Files","description":"Files the Developer Studio CLI creates, reads, and writes — in your project, on your user account, and via environment variables.","frontmatter":{"description":"Files the Developer Studio CLI creates, reads, and writes — in your project, on your user account, and via environment variables."},"headers":[],"relativePath":"cli/reference/project-files.md","filePath":"cli/reference/project-files.md"}'),r={name:"cli/reference/project-files.md"};function i(n,e,c,s,l,h){return o(),d("div",null,[...e[0]||(e[0]=[a('<div style="display:none;" hidden data-nosnippet>Are you an LLM? You can read better optimized documentation at /docs/cli/reference/project-files.md for this page in Markdown format</div><h1 id="project-files" tabindex="-1">Project Files <a class="header-anchor" href="#project-files" aria-label="Permalink to &quot;Project Files&quot;">​</a></h1><p>Describes every path <code>gsds</code> touches. Commit rules are stated per file.</p><h2 id="in-your-project" tabindex="-1">In your project <a class="header-anchor" href="#in-your-project" aria-label="Permalink to &quot;In your project&quot;">​</a></h2><h3 id="committed" tabindex="-1">Committed <a class="header-anchor" href="#committed" aria-label="Permalink to &quot;Committed&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Path</th><th>Purpose</th></tr></thead><tbody><tr><td><code>gsds.json</code></td><td>Project-root marker. <code>gsds</code> refuses to run outside a directory containing this file, apart from <code>gsds init</code></td></tr><tr><td><code>extensions_registry.json</code></td><td>Registry of widgets, scripts, and stylesheets in the project. Regenerated by <code>gsds build</code></td></tr><tr><td><code>connectors_registry.json</code></td><td>Registry of Connectors and composite Connectors. Regenerated by <code>gsds build</code></td></tr><tr><td><code>AGENTS.md</code></td><td>AI-agent-oriented project notes seeded by <code>gsds init</code></td></tr><tr><td><code>README.md</code></td><td>Human-oriented project notes seeded by <code>gsds init</code></td></tr><tr><td><code>.gitignore</code></td><td>Adds <code>.gsds/</code> to the ignore list</td></tr></tbody></table><h3 id="not-committed" tabindex="-1">Not committed <a class="header-anchor" href="#not-committed" aria-label="Permalink to &quot;Not committed&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Path</th><th>Purpose</th></tr></thead><tbody><tr><td><code>.gsds/</code></td><td>Connector-test capture output, with sensitive headers redacted. <code>gsds init</code> gitignores this directory</td></tr></tbody></table><h3 id="read-by-gsds-build" tabindex="-1">Read by <code>gsds build</code> <a class="header-anchor" href="#read-by-gsds-build" aria-label="Permalink to &quot;Read by `gsds build`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Path</th><th>Requirements</th></tr></thead><tbody><tr><td><code>widgets/&lt;name&gt;/widget.json</code></td><td>Must declare a non-empty <code>title</code> and <code>category</code>. Must declare exactly one of <code>source</code> or <code>content</code></td></tr><tr><td><code>widgets/&lt;name&gt;/connectors.json</code></td><td>May declare <code>connectors</code> and/or <code>composite_connectors</code>. Permalinks must be unique across widgets</td></tr></tbody></table><p>Scripts and stylesheets do not have their own source manifests — their entries live only in <code>extensions_registry.json</code> and are edited through <code>gsds script</code> and <code>gsds style</code>.</p><h2 id="in-your-user-account" tabindex="-1">In your user account <a class="header-anchor" href="#in-your-user-account" aria-label="Permalink to &quot;In your user account&quot;">​</a></h2><h3 id="os-keychain" tabindex="-1">OS keychain <a class="header-anchor" href="#os-keychain" aria-label="Permalink to &quot;OS keychain&quot;">​</a></h3><p><code>gsds</code> stores the session token in your operating system&#39;s keychain:</p><table tabindex="0"><thead><tr><th>Platform</th><th>Backend</th></tr></thead><tbody><tr><td>macOS</td><td>Keychain</td></tr><tr><td>Windows</td><td>Credential Store</td></tr><tr><td>Linux</td><td>Secret Service or keyutils via <code>@napi-rs/keyring</code></td></tr></tbody></table><p>Service name: <code>gainsight-developer-studio-cli</code>. Account name: <code>default</code>.</p><h3 id="file-fallback" tabindex="-1">File fallback <a class="header-anchor" href="#file-fallback" aria-label="Permalink to &quot;File fallback&quot;">​</a></h3><p>When the keychain is unavailable — no supported provider, headless CI, or a keychain error — <code>gsds</code> writes to <code>~/.config/gsds/credentials.json</code> at file mode <code>0600</code> and prints a one-time warning on stderr.</p><h2 id="environment-variables" tabindex="-1">Environment variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to &quot;Environment variables&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Effect</th></tr></thead><tbody><tr><td><code>GSDS_DISABLE_KEYCHAIN=1</code></td><td>Force the file-based credential fallback even when a keychain is available</td></tr></tbody></table><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li>Session pairing and TTL → <a href="./../authenticate.html">Authenticate</a></li><li>Missing-file error text and recovery → <a href="./troubleshooting.html">Troubleshooting</a></li><li>Command flags → <a href="./commands.html">Command reference</a></li></ul>',22)])])}const m=t(r,[["render",i]]);export{b as __pageData,m as default};
